"""Hoist side-effecting calls out of `assert` statements (#787).

`assert client.post(url).status_code == 201` loses BOTH the assertion and the
request under `python -O`, which strips asserts entirely — the test silently
becomes a no-op. Rewrites to:

    resp = client.post(url)
    assert resp.status_code == 201

Operates on source text (not `ast.unparse`) so comments and formatting elsewhere
in the file survive untouched.
"""

from __future__ import annotations

import ast
import pathlib
import sys

MUTATING = {"post", "put", "patch", "delete"}
MAYBE = {"get", "request"}


def _is_url_call(call: ast.Call) -> bool:
    return bool(
        call.args
        and isinstance(call.args[0], ast.Constant)
        and isinstance(call.args[0].value, str)
        and call.args[0].value.startswith("/")
    )


def _qualifies(node: ast.AST) -> bool:
    return (
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and (node.func.attr in MUTATING or (node.func.attr in MAYBE and _is_url_call(node)))
    )


def _offsets(source: str) -> list[int]:
    offs, total = [0], 0
    for line in source.splitlines(keepends=True):
        total += len(line)
        offs.append(total)
    return offs


def _span(offs: list[int], node: ast.AST) -> tuple[int, int]:
    return (
        offs[node.lineno - 1] + node.col_offset,
        offs[node.end_lineno - 1] + node.end_col_offset,
    )


def rewrite(path: pathlib.Path) -> int:
    source = path.read_text()
    tree = ast.parse(source)
    offs = _offsets(source)

    jobs: list[tuple[ast.Assert, ast.Call]] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Assert):
            continue
        # The OUTERMOST qualifying call: hoisting an inner one would leave the
        # outer call still inside the assert.
        found = next((c for c in ast.walk(node.test) if _qualifies(c)), None)
        if found is not None:
            jobs.append((node, found))
    if not jobs:
        return 0

    # Reverse source order so earlier offsets stay valid as we edit.
    jobs.sort(key=lambda j: j[0].lineno, reverse=True)
    for assert_node, call in jobs:
        cstart, cend = _span(offs, call)
        call_src = source[cstart:cend]
        # A hoisted multi-line call keeps its internal newlines; Black re-flows it.
        call_src = " ".join(part.strip() for part in call_src.splitlines())

        astart = offs[assert_node.lineno - 1]
        indent = " " * assert_node.col_offset
        var = "resp"
        source = (
            source[:cstart] + var + source[cend:]
        )  # replace the call inside the assert first
        source = source[:astart] + f"{indent}{var} = {call_src}\n" + source[astart:]
    path.write_text(source)
    return len(jobs)


if __name__ == "__main__":
    total = 0
    for p in sorted(pathlib.Path(sys.argv[1]).rglob("*.py")):
        n = rewrite(p)
        if n:
            print(f"{n:4d}  {p}")
            total += n
    print(f"hoisted {total}")

