def const_map(tree):
    """Module-level NAME = "/literal" bindings."""
    out={}
    for n in tree.body:
        if isinstance(n, ast.Assign) and isinstance(n.value, ast.Constant) and isinstance(n.value.value,str):
            for t in n.targets:
                if isinstance(t, ast.Name): out[t.id]=n.value.value
    return out

