    a = c.args[0] if c.args else None
    if isinstance(a, ast.Constant) and isinstance(a.value,str): return a.value.startswith("/")
    if isinstance(a, ast.JoinedStr) and a.values:
        f=a.values[0]
        return isinstance(f, ast.Constant) and isinstance(f.value,str) and f.value.startswith("/")
    if isinstance(a, ast.Name): return consts.get(a.id,"").startswith("/")
    return False

